import re
import logging
from subprocess import Popen, PIPE, STDOUT
from ta_ue_plugin_rtg.rpc.rpc_call_wraped import RpcCall
from ta_ue_plugin_rtg.rpc.uex_connection import UexConnection
from ta_ue_plugin_rtg.rpc.uex_connection import TaUeServer
from ta_ue_plugin_rtg.platform import get as get_platform


class DumpError(Exception):
    pass


class InvalidParameterError(Exception):
    pass


class ParametrizedUeCapabilities():
    def __init__(self, parameters_dict):
        """Initialize"""
        self.parameters_dict = parameters_dict
        self.logger = logging.getLogger('parametrized_ue_caps')

        self.uex_conn = UexConnection()
        self.rpc_call = RpcCall(self.uex_conn.rpc_conn, self.logger).call

        self.parameters_string = ''
        for key in self.parameters_dict:
            value = self.parameters_dict[key]
            if isinstance(value, bool) and value:
                self.parameters_string += key + '=' + 'on '
            elif isinstance(value, bool) and not value:
                self.parameters_string += key + '=' + 'off '
            else:
                self.parameters_string += key + '=' + str(value) + ' '

    def get_hex_value(self):
        """Return hex string using UE_generator and uesim-dump"""
        self.logger.info("UE_generator input: {}".format(self.parameters_string))
        if TaUeServer().get_hostname() == '127.0.0.1':
            ue_gen_out, output = self._run_locally()
        else:
            ue_gen_out, output = self._run_remotely()

        self.logger.debug("UE_generator output / uesim-dump input: {}".format(ue_gen_out))
        self.logger.debug("uesim-dump output: {}".format(output))

        status = re.search(r'encoded-values\(([0-9])\), errors\(([0-9])\)', output)
        # encoded_values = int(status.group(1))
        errors = int(status.group(2))

        try:
            empty_files = re.search(r'suspiciously-empty-files\(([0-9])\)', output).group(1)
        except AttributeError:
            empty_files = 0

        empty_files = int(empty_files)
        if empty_files > 0:
            raise InvalidParameterError(re.search(r'\*{4}(.+)\*{4}', ue_gen_out).group(1))
        elif errors > 0:
            raise DumpError("There have beeen errors during conversion from asn to hex format:")
        else:
            hex = re.search(r'ASN1-VALUE \w+ [\w-]+ (\w+)', output).group(1)
            return hex

    def _run_locally(self):
        platform = get_platform()
        ue_generator = Popen(('/usr/{}/bin/UE_generator'.format(platform), '-f', '-'), stdout=PIPE, stdin=PIPE, stderr=STDOUT)
        ue_generator_output = ue_generator.communicate(input=self.parameters_string.encode())[0]
        p = Popen(('/usr/{}/bin/uesim-dump'.format(platform), '-a', '-'), stdin=PIPE, stdout=PIPE, stderr=STDOUT)
        ue_sum_dump_output = p.communicate(ue_generator_output)[0]
        return ue_generator_output, ue_sum_dump_output

    def _run_remotely(self):
        ue_generator_output = self.rpc_call(method="run_ue_generator", params=self.parameters_string, log_msg="UE({0}) - Run UE_generator")
        ue_sum_dump_output = self.rpc_call(method="run_uesim_dump", params=ue_generator_output, log_msg="UE({0}) - Run uesim-dump")
        return ue_generator_output, ue_sum_dump_output
